package com.wandertrace.service;
import com.wandertrace.dto.TripDtos.*;import com.wandertrace.exception.*;import java.time.*;import java.util.*;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;
@Service public class TripService {private final JdbcTemplate db;private final TripAccessService access;public TripService(JdbcTemplate db,TripAccessService access){this.db=db;this.access=access;}public List<Trip> list(UUID user){return db.queryForList("select t.id,t.title,t.description,t.start_date,t.end_date,t.cover_image_url,tm.role from trips t join trip_members tm on tm.trip_id=t.id where tm.user_id=? order by t.start_date desc nulls last",user).stream().map(this::trip).toList();}public Trip get(UUID user,UUID id){access.requireView(user,id);return trip(one("select t.id,t.title,t.description,t.start_date,t.end_date,t.cover_image_url,tm.role from trips t join trip_members tm on tm.trip_id=t.id where t.id=? and tm.user_id=?",id,user));}@Transactional public Trip create(UUID user,CreateTrip r){UUID id=UUID.randomUUID();db.update("insert into trips(id,user_id,title,description,start_date,end_date,cover_image_url) values(?,?,?,?,?,?,?)",id,user,r.title(),r.description(),r.startDate(),r.endDate(),r.coverImageUrl());db.update("insert into trip_members(trip_id,user_id,role) values(?,?,?)",id,user,"OWNER");return get(user,id);}@Transactional public Trip update(UUID user,UUID id,UpdateTrip r){access.requireEdit(user,id);db.update("update trips set title=?,description=?,start_date=?,end_date=?,cover_image_url=?,updated_at=now() where id=?",r.title(),r.description(),r.startDate(),r.endDate(),r.coverImageUrl(),id);return get(user,id);}public void delete(UUID user,UUID id){access.requireOwner(user,id);db.update("delete from trips where id=?",id);}public List<Member> members(UUID user,UUID trip){access.requireView(user,trip);return db.queryForList("select u.id user_id,u.email,u.display_name,tm.role from trip_members tm join users u on u.id=tm.user_id where tm.trip_id=? order by tm.created_at",trip).stream().map(this::member).toList();}@Transactional public Member addMember(UUID user,UUID trip,AddMember r){access.requireOwner(user,trip);var users=db.queryForList("select id,email,display_name from users where lower(email)=lower(?)",r.email());if(users.isEmpty())throw new NotFoundException("User not found");var target=(UUID)users.getFirst().get("id");if(!db.queryForList("select id from trip_members where trip_id=? and user_id=?",trip,target).isEmpty())throw new DuplicateResourceException("User is already a collaborator");db.update("insert into trip_members(trip_id,user_id,role) values(?,?,?)",trip,target,r.role());return new Member(target,(String)users.getFirst().get("email"),(String)users.getFirst().get("display_name"),r.role());}public void changeMember(UUID user,UUID trip,UUID member,UpdateMember r){access.requireOwner(user,trip);int changed=db.update("update trip_members set role=?,updated_at=now() where trip_id=? and user_id=? and role <> 'OWNER'",r.role(),trip,member);if(changed==0)throw new AccessDeniedException();}public void removeMember(UUID user,UUID trip,UUID member){access.requireOwner(user,trip);int changed=db.update("delete from trip_members where trip_id=? and user_id=? and role <> 'OWNER'",trip,member);if(changed==0)throw new AccessDeniedException();}private Map<String,Object> one(String q,Object... args){var r=db.queryForList(q,args);if(r.isEmpty())throw new NotFoundException("Trip not found");return r.getFirst();}private Trip trip(Map<String,Object> r){return new Trip((UUID)r.get("id"),(String)r.get("title"),(String)r.get("description"),toDate(r.get("start_date")),toDate(r.get("end_date")),(String)r.get("cover_image_url"),(String)r.get("role"));}private Member member(Map<String,Object> r){return new Member((UUID)r.get("user_id"),(String)r.get("email"),(String)r.get("display_name"),(String)r.get("role"));}private LocalDate toDate(Object d){return d==null?null:((java.sql.Date)d).toLocalDate();}}
